/**
 * 搜打撤（PT_SOUDACHE）· 守门员 Boss 数据表
 * ---------------------------------------------------------------------------
 * 🔴 **本文件存在的唯一理由：切断循环导入。**
 *
 * 背景（2026-10-20 I-1 走查实测暴露）：
 *   守门员波次表原本写在 `pt-soudache-system.ts` 里，而 `battle-scene.ts` 的
 *   `newBattle()` 需要 `findGuardianBossSpec(waveIndex)`。直接 import 形成：
 *
 *     battle-scene → pt-soudache-system → title-phase → game-mode
 *                  → fixed-battle-configs → battle → global-scene → battle-scene
 *
 *   环在 `battle-scene` 初始化中途闭合 ⇒ `globalScene` 拿到半成品 ⇒
 *   `FixedBattleConfig is not a constructor` ⇒ **产物 B 启动即黑屏**
 *   （tsc / vite build 全绿，只有真跑才现形）。
 *
 *   ⇒ 数据表抽到本文件后，`battle-scene` 只依赖「物种枚举 + 纯数组」，
 *     零 Phase / 零 globalScene / 零副作用，环被打断。
 *
 * ⚠️ **本文件禁止 import 任何带副作用的模块**（Phase / globalScene / battle-scene）。
 *    只允许：枚举常量、纯类型。
 *
 * 产物来源：`loading-scene-By2k7Qfx.js` @3640379 起（A 版 unminified）
 *   `uPe` → GUARDIAN_BOSS_SPECS · `cPe` → findGuardianBossSpec
 *   `Qne` → GUARDIAN_EXTRA_TALENT_POOL · `NPe` → GUARDIAN_JIRACHI_POOL
 *   `Jne` → GUARDIAN_REGIONAL_TALENTS
 */

import { SpeciesId } from "#enums/species-id";

/** 守门员 Boss 的一档配置（产物 `uPe` 数组元素） */
export interface GuardianBossSpec {
  /** 触发波次 */
  wave: number;
  /** 物种候选池 */
  speciesPool: number[];
  /** 分段数（`setBoss(true, segments)`） */
  segments: number;
  /**
   * 按物种返回天赋 id 列表。
   * ⚠️ 函数在**存档往返后可能丢失**（JSON 化）⇒ 消费方必须兜底：
   *    `buildGuardianTalentIds({ talentForSpecies: () => [], ...spec }, id)`
   */
  talentForSpecies: (speciesId: number) => string[];
  /** AI 模式（`jirachi` / `gardevoir` / undefined = 默认） */
  aiModeForSpecies?: (speciesId: number) => string | undefined;
  /** 额外天赋池 + 抽取区间 [min, max] */
  extraTalentPool?: readonly string[];
  extraTalentCount?: [number, number];
  /** 额外道具数 */
  itemBonus: number;
  /** 击败奖励 PT */
  rewardPt: number;
}

/** 产物 `Qne` —— 通用「尊」系额外天赋池 */
export const GUARDIAN_EXTRA_TALENT_POOL: readonly string[] = [
  "liliang_zhizun", "fangyu_zhizun", "tegong_zhizun", "tefang_zhizun", "sudu_zhizun", "tili_zhizun",
];

/** 产物 `NPe` —— 杰拉奇专属额外天赋池 */
export const GUARDIAN_JIRACHI_POOL: readonly string[] = [
  "liliang_zuzhou", "fangyu_bengkui", "moli_kujie", "mokang_posui", "chihuan_zhizhou", "shengming_liushi",
];

/** 产物 `Jne` —— 三御三家的区域天赋表 */
export const GUARDIAN_REGIONAL_TALENTS: Readonly<Record<number, readonly string[]>> = {
  [SpeciesId.REGIROCK]: ["shiqishidai"],
  [SpeciesId.REGICE]: ["bingheqi"],
  [SpeciesId.REGISTEEL]: ["gongyegeming"],
};

/** 产物 `uPe` —— 守门员 Boss 波次表（3 档） */
export const GUARDIAN_BOSS_SPECS: readonly GuardianBossSpec[] = [
  {
    wave: 100,
    speciesPool: [SpeciesId.REGIROCK, SpeciesId.REGICE, SpeciesId.REGISTEEL],
    segments: 8,
    talentForSpecies: (n) => [...(GUARDIAN_REGIONAL_TALENTS[n] ?? [])],
    itemBonus: 0,
    rewardPt: 6000,
  },
  {
    wave: 150,
    speciesPool: [SpeciesId.REGIROCK, SpeciesId.REGICE, SpeciesId.REGISTEEL],
    segments: 12,
    talentForSpecies: (n) => [...(GUARDIAN_REGIONAL_TALENTS[n] ?? [])],
    extraTalentPool: GUARDIAN_EXTRA_TALENT_POOL,
    extraTalentCount: [1, 2],
    itemBonus: 5,
    rewardPt: 15000,
  },
  {
    wave: 190,
    speciesPool: [SpeciesId.INFERNAPE, SpeciesId.JIRACHI, SpeciesId.GARDEVOIR],
    segments: 12,
    talentForSpecies: (n) => {
      switch (n) {
        case SpeciesId.INFERNAPE:
          return ["menghuo_menghuo", "dengjiajiaohuan", "shengmingjiqu", "shengmingjiqu", "shengmingjiqu", "shengmingjiqu", ...GUARDIAN_EXTRA_TALENT_POOL];
        case SpeciesId.JIRACHI:
          return ["xingxiang", "fouji_tailai", ...GUARDIAN_JIRACHI_POOL];
        case SpeciesId.GARDEVOIR:
          return ["yijian_qingyuan", "busizishen", "mengxing", "mengjing_hubi", "shimeng", "tongxing"];
        default:
          return [];
      }
    },
    aiModeForSpecies: (n) =>
      n === SpeciesId.JIRACHI ? "jirachi" : n === SpeciesId.GARDEVOIR ? "gardevoir" : undefined,
    itemBonus: 12,
    rewardPt: 50000,
  },
];

/** 产物 `cPe` —— 按波次取守门员配置 */
export function findGuardianBossSpec(wave: number): GuardianBossSpec | undefined {
  return GUARDIAN_BOSS_SPECS.find((s) => s.wave === wave);
}
