/**
 * A `PokemonType` represents the type of a Pokemon or its moves.
 * @see {@link https://bulbapedia.bulbagarden.net/wiki/Type}
 */
export enum PokemonType {
  /** Also known as {@link https://bulbapedia.bulbagarden.net/wiki/Type#Typeless | typeless}. */
  UNKNOWN = -1,

  NORMAL = 0,
  FIGHTING,
  FLYING,
  POISON,
  GROUND,
  ROCK,
  BUG,
  GHOST,
  STEEL,
  FIRE,
  WATER,
  GRASS,
  ELECTRIC,
  PSYCHIC,
  ICE,
  DRAGON,
  DARK,
  FAIRY,

  /**
   * A pseudo-type used for Terastallization.
   * @see {@link https://bulbapedia.bulbagarden.net/wiki/Stellar_(type)}
   */
  STELLAR,

  /**
   * PKRC custom type (mod-only). Added after `STELLAR` with value `19`.
   * Used as the attacking type of the mod's custom move 归无之光 (`MoveId.NIHIL_LIGHT`).
   * In the type chart it is super-effective (2x) against almost everything and takes
   * 0.5x from everything except itself (cf. `getTypeDamageMultiplier`).
   */
  CS,
}

/** Types that a Pokemon can naturally have; excludes Typeless and Stellar */
export type RegularPokemonType = Exclude<PokemonType, PokemonType.UNKNOWN | PokemonType.STELLAR>;

/** The largest legal value for a {@linkcode PokemonType} (includes Stellar and the mod's custom `CS`) */
export const MAX_POKEMON_TYPE = PokemonType.CS;
