import { registerCallingCardSystem } from "./callingcard-system";
import { registerChiXinSystem, registerChiXinWindowExpireHandler } from "./chixin-system";
import { registerDianXinSystem } from "./dianxin-system";
import { registerHealerConversionTargetProvider, registerHealerSystem } from "./healer-system";
import {
  registerJiemingShieldExpireHandler,
  registerSeaGuardJiemingModule,
  registerSeaGuardSystem,
} from "./manaphy-system";
import {
  registerMeloettaDanceExpireHandler,
  registerMeloettaJiemingModule,
  registerMeloettaStatusProvider,
  registerMeloettaSystem,
} from "./meloetta-system";
import { registerMewJiemingModule, registerMewStatusProvider, registerMewSystem } from "./mew-system";
import { initializeTalentSystem } from "./talent-system";

/**
 * 初始化全部魔改系统。
 * 由 `initializeGame()`（`src/init/init.ts`）在**上游初始化之后**调用一次。
 */
export function initializeModSystems(): void {
  // ── 系统主体注册（命座编解码 → 各系统的 codex / 状态提供者）──
  initializeTalentSystem();
  registerCallingCardSystem();
  registerChiXinSystem();
  registerDianXinSystem();
  registerHealerSystem();
  registerMeloettaSystem();
  registerMewSystem();
  registerSeaGuardSystem();

  // ── 解明模块（多角色共享招式/冷却体系）──
  registerSeaGuardJiemingModule();
  registerMeloettaJiemingModule();
  registerMewJiemingModule();

  // ── 状态图标 / 效果过期回调 / 治疗转换 ──
  registerMeloettaStatusProvider();
  registerMewStatusProvider();
  registerMeloettaDanceExpireHandler();
  registerChiXinWindowExpireHandler();
  registerJiemingShieldExpireHandler();
  registerHealerConversionTargetProvider();
}

