// ===========================================================================
// 2. 辅助（周种子 RNG / 格式化 / 搜索归一化）
// ===========================================================================

/** 周种子 key（产物 `Ule`） */
export function weeklyKey(parts: unknown[]): string {
  return parts.join("|");
}

/** FNV-1a 字符串散列（产物 `dle`） */
export function hashString(str: string): number {
  let hash = 2166136261;
  for (let i = 0; i < str.length; i++) {
    hash ^= str.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return hash >>> 0;
}

/** mulberry32 PRNG（产物 `Mle`） */
export function mulberry32(seed: number): () => number {
  let s = seed >>> 0;
  return () => {
    s = (s + 1831565813) | 0;
    let t = Math.imul(s ^ (s >>> 15), 1 | s);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** 周种子浮点（产物 `Dle`）：`[seedParts] → hash → mulberry32 → [0,1)` */
export function weeklyRandomFloat(seedParts: unknown[]): number {
  return mulberry32(hashString(weeklyKey(seedParts)))();
}

/** 周种子整数（产物 `Pw`） */
export function weeklyRandomInt(seedParts: unknown[], min: number, max: number): number {
  return max > min ? min + Math.floor(weeklyRandomFloat(seedParts) * (max - min + 1)) : min;
}

/** 周固定深渊判定（产物 `_w`）：层数 ≥ 6 */
export function isWeeklyFixedAbyss(level: number): boolean {
  return Number.isFinite(level) && level >= ABYSS_WEEKLY_FIXED_MIN_LEVEL;
}

/** 百分比格式化（产物 `wI`，keepName `"percent"`） */
export function percent(n: number): string {
  return `${Math.round(n * 1e3) / 10}%`;
}

/** 搜索 token 归一化（产物 `tF`，keepName `"normalize"`） */
export function normalizeEryouSearchToken(n: string): string {
  return n
    .normalize("NFKC")
    .toLowerCase()
    .replace(/^eryou_form_|^eryou-item:/, "")
    .replace(/[\s\p{P}\p{S}]/gu, "");
}

/** 深渊重复掉落石数（产物 `Nle`）：按层数查概率表掷骰（**用 Math.random，非周种子**） */
export function rollAbyssRepeatStones(level: number): number {
  const lv = Number.isFinite(level) ? Math.min(Math.max(Math.trunc(level), 1), ABYSS_MAX_LEVEL) : 1;
  return lv <= 2
    ? Math.random() < ABYSS_REPEAT_DROP_L1_L2[lv - 1]
      ? 1
      : 0
    : lv <= 5
      ? Math.random() < ABYSS_REPEAT_DROP_L3_L5[lv - 3]
        ? 1
        : 0
      : lv === 6
        ? Math.random() < ABYSS_REPEAT_DROP_L6
          ? 1
          : 0
        : lv <= 8
          ? 1 + (Math.random() < ABYSS_REPEAT_DROP_L7_L8[lv - 7] ? 1 : 0)
          : 1 + (Math.random() < ABYSS_REPEAT_DROP_L9_L10[lv - 9] ? 1 : 0);
}

/** 隐藏平衡查询（产物 `bae` "getAbyssHiddenBalance"） */
export function getAbyssHiddenBalance(level: number): { dmgMult: number; bulkMult: number } {
  return ABYSS_HIDDEN_BALANCE[level] ?? { dmgMult: 1, bulkMult: 1 };
}

/** 搜索展示文本（产物 `Efe` "eryouItemSearchText"） */
export function eryouItemSearchText(a: string, b: string): string {
  return `${normalizeEryouSearchToken(a)} ${normalizeEryouSearchToken(b)}`;
}

// ===========================================================================
// 3. 深渊规则（F-11 目标 11 项）—— 逐字还原产物
// ===========================================================================

/** 取第 `level` 层配置（产物 `Z1` "abyssConfigAt"；越界 clamp，非有限值返回 null） */
export function abyssConfigAt(level: number): AbyssLevelConfig | null {
  if (!Number.isFinite(level)) {
    return null;
  }
  const idx = Math.min(Math.max(Math.trunc(level), 1), ABYSS_LEVEL_CONFIG.length) - 1;
  return ABYSS_LEVEL_CONFIG[idx] ?? null;
}

/** 已解锁的地牢进度层数（产物 `Mde` "abyssEntryProgress"）；无记录返回 1 */
export function abyssEntryProgress(data: { dungeonUnlocks: Record<string, unknown> }): number {
  const levels = Object.values(data.dungeonUnlocks).map(Number).filter(Number.isFinite);
  // 产物 `TE = YR.length`（地牢难度层数）
  const maxLevel = Array.isArray(YR) ? YR.length : 0;
  return levels.length ? Math.min(Math.max(...levels), maxLevel) : 1;
}

/** 是否已解锁深渊入口（产物 `VN` "abyssEntryUnlocked"）：任一地牢难度 ≥ 5 */
export function abyssEntryUnlocked(data: { dungeonUnlocks: Record<string, unknown> }): boolean {
  return Object.values(data.dungeonUnlocks).some((v) => Number(v) >= ABYSS_ENTRY_UNLOCK_THRESHOLD);
}

/** 深渊当前已解锁层数（产物 `kN` "abyssUnlockedLevel"） */
export function abyssUnlockedLevel(data: { abyssUnlocked: unknown }): number {
  const raw = Number(data.abyssUnlocked);
  return Math.min(Math.max(Number.isFinite(raw) ? Math.trunc(raw) : 1, 1), ABYSS_MAX_LEVEL);
}

/** 本周已首通的深渊层数（产物 `_de` "abyssWeeklyClaimed"） */
export function abyssWeeklyClaimed(data: { abyssFirstClear: Record<number, unknown> }): number {
  let count = 0;
  for (let i = 1; i <= ABYSS_MAX_LEVEL; i++) {
    if (data.abyssFirstClear[i]) {
      count++;
    }
  }
  return count;
}

/** 周种子组成部分（产物 `Ple` "abyssWeeklyParts"） */
export function abyssWeeklyParts(level: number, a: number, kind: string, index: number): unknown[] {
  return [getEryouWeekKey(), Math.trunc(level), Math.trunc(a), kind, index];
}

/** 深渊随机取数（产物 `Gw` "abyssRoll"）：周固定层用周种子，否则用普通 RNG */
export function abyssRoll(
  level: number,
  a: number,
  kind: string,
  index: number,
  min: number,
  max: number,
): number {
  return isWeeklyFixedAbyss(level)
    ? weeklyRandomInt(abyssWeeklyParts(level, a, kind, index), min, max)
    : randIntRange(min, max);
}

/** 重复通关掉石文案（产物 `Pde` "abyssRepeatDropText"） */
export function abyssRepeatDropText(level: number): string {
  const lv = Math.min(Math.max(Math.trunc(level), 1), ABYSS_MAX_LEVEL);
  return lv <= 2
    ? `${percent(ABYSS_REPEAT_DROP_L1_L2[lv - 1])} 概率 1 颗`
    : lv <= 5
      ? `${percent(ABYSS_REPEAT_DROP_L3_L5[lv - 3])} 概率 1 颗`
      : lv === 6
        ? `${percent(ABYSS_REPEAT_DROP_L6)} 概率 1 颗`
        : lv <= 8
          ? `固定 1 颗 + ${percent(ABYSS_REPEAT_DROP_L7_L8[lv - 7])} 再 1 颗`
          : `固定 1 颗 + ${percent(ABYSS_REPEAT_DROP_L9_L10[lv - 9])} 再 1 颗`;
}

/** 深渊层详情（产物 `lie` "abyssLevelInfo"） */
export function abyssLevelInfo(
  data: {
    abyssUnlocked: unknown;
    abyssFirstClear: Record<number, unknown>;
    dungeonUnlocks: Record<string, unknown>;
  },
  level: number,
): {
  level: number;
  unlocked: boolean;
  firstClearClaimed: boolean;
  firstClearStones: number;
  repeatText: string;
  levelRange: [number, number];
  minBst: number;
  buffText: string;
  mechanismText: string;
  weeklyFixed: boolean;
  waveCount: number;
} {
  const lv = Math.min(Math.max(Math.trunc(level), 1), ABYSS_MAX_LEVEL);
  const cfg = ABYSS_LEVEL_CONFIG[lv - 1];
  const bulkMult = 2 + cfg.buffTier;
  const atkMult = abyssAttackBuffMultiplier(cfg.buffTier);
  const buffText =
    cfg.buffCount > 0
      ? `每只敌人随机 ${cfg.buffCount} 项（可重复）：${ABYSS_BUFF_LABELS.attack}（攻击/特攻 ×${atkMult}）、${ABYSS_BUFF_LABELS.defense}（防御/特防/HP ×${bulkMult}）、${ABYSS_BUFF_LABELS.evasion} / ${ABYSS_BUFF_LABELS.crit} +${cfg.buffTier + 1} 级`
      : "无";
  const mechanismText =
    cfg.mechanismCount > 0
      ? `开局公示 ${cfg.mechanismCount} 项：指定属性招式 -50%，或物理 / 特殊 / 单体 / 群体 -30%`
      : "无";
  return {
    level: lv,
    unlocked: lv <= abyssUnlockedLevel(data) && abyssEntryUnlocked(data),
    firstClearClaimed: !!data.abyssFirstClear[lv],
    firstClearStones: cfg.firstClearStones,
    repeatText: abyssRepeatDropText(lv),
    levelRange: cfg.levelRange,
    minBst: cfg.minBst,
    buffText,
    mechanismText,
    weeklyFixed: lv >= ABYSS_WEEKLY_FIXED_MIN_LEVEL,
    waveCount: ABYSS_WAVE_COUNT,
  };
}

/** 攻击强化倍率（产物 `$ae` "abyssAttackBuffMultiplier"）：tier clamp 0..2 */
export function abyssAttackBuffMultiplier(tier: number): number {
  const i = Number.isFinite(tier)
    ? Math.min(Math.max(Math.trunc(tier), 0), ABYSS_ATTACK_BUFF_MULT.length - 1)
    : 0;
  return ABYSS_ATTACK_BUFF_MULT[i] ?? 1;
}

/** 搜索匹配（产物 `rfe` "matchesEryouItemSearch"）：查询按空白分词，逐 token 归一化后全命中 */
export function matchesEryouItemSearch(haystack: string, query: string): boolean {
  return query
    .normalize("NFKC")
    .trim()
    .split(/\s+/)
    .map(normalizeEryouSearchToken)
    .filter(Boolean)
    .every((token) => haystack.includes(token));
}

