import { globalScene } from "#app/global-scene";

/** 玩家名 → 占位符 映射（产物 `Ow` 的返回值） */
export interface PlayerNamePlaceholders {
  names: string[];
  placeholders: string[];
}

/**
 * 产物 `Ow` — 取玩家名占位符映射（用于日志脱敏）。
 * 注：默认参数 `E.getPlayerField()` 在产物中即如此（延迟求值）。
 */
export function getPlayerNamePlaceholders(
  field: { getNameToRender(): string }[] = globalScene.getPlayerField(),
): PlayerNamePlaceholders {
  const names: string[] = [];
  const placeholders: string[] = [];
  for (let i = 0; i < field.length; i++) {
    names.push(field[i].getNameToRender());
    placeholders.push(`POKEMON${i + 1}`);
  }
  return { names, placeholders };
}

/** 产物 `Iw` — 把玩家名替换为占位符（脱敏） */
export function maskPlayerNames(text: string, s: PlayerNamePlaceholders): string {
  for (let i = 0; i < s.names.length; i++) {
    if (s.names[i]) {
      text = text.split(s.names[i]).join(s.placeholders[i]);
    }
  }
  return text;
}

/** 产物 `tU` — 还原占位符为玩家名 */
export function unmaskPlayerNames(text: string, s: PlayerNamePlaceholders): string {
  for (let i = 0; i < s.placeholders.length; i++) {
    text = text.split(s.placeholders[i]).join(s.names[i]);
  }
  return text;
}

/** 已解析配置缓存（产物 `vg`） */
let cachedConfig: string | null | undefined;

/** 产物 `NIe` — 从 URL 查询参数 / localStorage 解析调试配置 */
export function resolvePersistedConfig(): string | null {
  if (typeof window === "undefined") return null;
  const fromQuery = new URLSearchParams(window.location.search).get("debug");
  if (fromQuery) return fromQuery;
  try {
    return window.localStorage.getItem("PT_DEBUG");
  } catch {
    return null;
  }
}

/** 产物 `uIe` — 取调试配置（`globalThis.PT_DEBUG` 优先，其次缓存/持久化） */
export function getConfig(): string | null | undefined {
  const fromGlobal = (globalThis as any).PT_DEBUG;
  if (typeof fromGlobal === "string" && fromGlobal.trim()) return fromGlobal.trim();
  if (cachedConfig === undefined) cachedConfig = resolvePersistedConfig();
  return cachedConfig;
}

/** 产物 `cIe` — 判断某日志类别是否启用（支持 `1` / `all` / `*` / 逗号分隔列表） */
export function isDebugEnabled(category: string): boolean {
  const config = getConfig();
  if (!config) return false;
  if (config === "1" || config === "all" || config === "*") return true;
  return config.split(",").some(c => c.trim() === category);
}

/** 产物 `z` — 分类调试日志（仅当该类被启用时输出） */
export function debugLog(category: string, ...args: any[]): void {
  if (isDebugEnabled(category)) {
    console.log(`[${category}]`, ...args);
  }
}
