// ─────────────────────────────────────────────────────────────
// 6. 预告信槽位 UI（A3-补 第九批落位：产物 `NT` / `oee` = CallingCardGauge）
// ─────────────────────────────────────────────────────────────
// ⚠️ 产物中同一个 `NT` 类被四套系统槽位复用（callingcard `ige` / chixin `nge` / nianli `Age` /
//    healer `ae` 四个 style），keepName 取首个使用者 CallingCardGauge；本批只落默认（callingcard）style，
//    其余三个 style 随各系统批次补齐，类可直接复用。

/** 槽位圆点半径（产物 `dr`） */
const GAUGE_PIP_RADIUS = 3.2;
/** 槽位圆点间距（产物 `z1e`） */
const GAUGE_PIP_SPACING = 8;

/** 槽位样式（产物 `ige`，默认 = 偷心怪盗预告信） */
export interface CallingCardGaugeStyle {
  name: string;
  glowColor: number;
  flashColor: number;
  wispColors: number[];
  outlineColor: number;
  emptyColor: number;
  emptyInnerColor: number;
  /** 阈值分隔线颜色（缺省回退 glowColor） */
  thresholdColor?: number;
  /** 阈值分隔线段号（1..max，缺省不画） */
  thresholdSegment?: number;
  /** 点亮态贴图（缺省 "constellation_flame"，不存在时退化为圆点） */
  litTexture?: string;
}

/** 偷心怪盗槽位默认样式（产物 `ige`；颜色由产物十进制转十六进制） */
export const CALLINGCARD_GAUGE_STYLE: CallingCardGaugeStyle = {
  name: "container_calling_card_gauge",
  glowColor: 0xff3b52, // 产物 ege=16726866
  flashColor: 0xffe9ec, // 产物 tge=16771564
  wispColors: [0xff3b52, 0xd7263d, 0xff8a95, 0xb3122b], // 产物 sge
  outlineColor: 0x120a0c, // 产物 q1e=1182220
  emptyColor: 0x4a4448, // 产物 Hg=4867144
  emptyInnerColor: 0x3a3438, // 产物 pg=3814456
};

/**
 * 产物 `oee`/`NT` — 资源槽位（pip 圆点 + 火焰点亮 + 满槽磷光 + 获得闪烁）。
 * Phaser Container 子类；由 `PlayerBattleInfo` 创建（`new CallingCardGauge(-37, -22)`），
 * `BattleInfo.updateCallingCardGauge(pokemon)` 每帧驱动。
 */
export class CallingCardGauge extends Phaser.GameObjects.Container {
  private glow: Phaser.GameObjects.Graphics;
  private pips: Phaser.GameObjects.Graphics;
  private flameLayer: Phaser.GameObjects.Container;
  private wispLayer: Phaser.GameObjects.Container;
  private glowTween: Phaser.Tweens.Tween | null = null;
  private wispTimer: Phaser.Time.TimerEvent | null = null;
  private max = 4;
  private value = -1;
  private windowActive = false;
  private activeTween: Phaser.Tweens.Tween | null = null;
  private style: CallingCardGaugeStyle;

  constructor(x: number, y: number, style: CallingCardGaugeStyle = CALLINGCARD_GAUGE_STYLE) {
    super(globalScene, x, y);
    this.style = style;
    this.setName(style.name);

    this.glow = globalScene.add.graphics();
    this.glow.setBlendMode(Phaser.BlendModes.ADD);
    this.glow.setAlpha(0);
    this.add(this.glow);

    this.pips = globalScene.add.graphics();
    this.add(this.pips);

    this.flameLayer = globalScene.add.container(0, 0);
    this.add(this.flameLayer);

    this.wispLayer = globalScene.add.container(0, 0);
    this.add(this.wispLayer);

    this.setVisible(false);
  }

  /** 第 index 个 pip 的 x 坐标（以中心对称分布） */
  private pipX(index: number): number {
    return (index - (this.max - 1) / 2) * GAUGE_PIP_SPACING;
  }

  setMax(max: number): void {
    const m = Math.max(1, Math.floor(max) || 1);
    if (m !== this.max) {
      this.max = m;
      if (this.value >= 0) {
        this.draw();
      }
    }
  }

  setValue(value: number, animate = false): void {
    const v = Math.max(0, Math.min(this.max, value));
    const prev = this.value;
    if (prev !== v) {
      this.value = v;
      this.draw();
      if (animate && prev >= 0 && v > prev) {
        for (let i = prev; i < v; i++) {
          this.playGainFlash(i);
        }
      }
      if (v >= this.max) {
        this.startWisps();
      } else {
        this.stopWisps();
      }
    }
  }

  hide(): void {
    this.stopWisps();
    this.clearFlames();
    this.setWindowActive(false);
    this.value = -1;
    this.setVisible(false);
  }

  /** 满槽「窗口激活」脉冲（产物 setWindowActive） */
  setWindowActive(active: boolean): void {
    if (active !== this.windowActive) {
      this.windowActive = active;
      this.activeTween?.remove();
      this.activeTween = null;
      this.setScale(1);
      if (active) {
        this.activeTween = globalScene.tweens.add({
          targets: this,
          scaleX: 1.18,
          scaleY: 1.18,
          duration: 520,
          yoyo: true,
          repeat: -1,
          ease: "Sine.easeInOut",
        });
      }
    }
  }

  private clearFlames(): void {
    this.flameLayer.each((child: Phaser.GameObjects.GameObject) => globalScene.tweens.killTweensOf(child));
    this.flameLayer.removeAll(true);
  }

  /** 单个点亮 pip（贴图存在时用火焰图 + 呼吸动画，否则退化为双层圆点） */
  private createFlame(x: number, index: number): void {
    const texture = this.style.litTexture ?? "constellation_flame";
    if (!globalScene.textures?.exists?.(texture)) {
      this.pips.fillStyle(this.style.glowColor, 1);
      this.pips.fillCircle(x, 0, GAUGE_PIP_RADIUS + 0.6);
      this.pips.fillStyle(this.style.flashColor, 0.9);
      this.pips.fillCircle(x, 0, GAUGE_PIP_RADIUS * 0.55);
      return;
    }
    const flame = globalScene.add.image(x, 0, texture);
    flame.setName("calling-card-flame");
    flame.setDisplaySize(GAUGE_PIP_RADIUS * 1.9, GAUGE_PIP_RADIUS * 3.1);
    this.flameLayer.add(flame);
    const baseScaleX = flame.scaleX;
    const baseScaleY = flame.scaleY;
    const duration = 340 + index * 70;
    globalScene.tweens.add({
      targets: flame,
      scaleY: { from: baseScaleY * 0.84, to: baseScaleY * 1.18 },
      scaleX: { from: baseScaleX * 1.1, to: baseScaleX * 0.9 },
      y: { from: 0.4, to: -0.4 },
      duration,
      yoyo: true,
      repeat: -1,
      ease: "Sine.easeInOut",
    });
    globalScene.tweens.add({
      targets: flame,
      alpha: { from: 0.75, to: 1 },
      duration: duration * 1.3,
      yoyo: true,
      repeat: -1,
      ease: "Sine.easeInOut",
    });
  }

  private draw(): void {
    const pips = this.pips;
    pips.clear();
    this.clearFlames();
    for (let i = 0; i < this.max; i++) {
      const x = this.pipX(i);
      if (i < this.value) {
        this.createFlame(x, i);
      } else {
        pips.fillStyle(this.style.outlineColor, 1);
        pips.fillCircle(x, 0, GAUGE_PIP_RADIUS + 0.8);
        pips.fillStyle(this.style.emptyColor, 1);
        pips.fillCircle(x, 0, GAUGE_PIP_RADIUS);
        pips.fillStyle(this.style.emptyInnerColor, 1);
        pips.fillCircle(x, 0.4, GAUGE_PIP_RADIUS * 0.62);
      }
    }
    const segment = this.style.thresholdSegment;
    if (segment && segment >= 1 && segment <= this.max) {
      pips.lineStyle(1.1, this.style.thresholdColor ?? this.style.glowColor, 0.95);
      pips.strokeCircle(this.pipX(segment - 1), 0, GAUGE_PIP_RADIUS + 1.9);
    }
    this.glow.clear();
    for (let i = 0; i < this.max; i++) {
      this.glow.fillStyle(this.style.glowColor, 0.35);
      this.glow.fillCircle(this.pipX(i), 0, GAUGE_PIP_RADIUS + 2.4);
    }
  }

  /** 获得层数时的单点闪烁（产物 playGainFlash） */
  private playGainFlash(index: number): void {
    const flash = globalScene.add.circle(this.pipX(index), 0, GAUGE_PIP_RADIUS + 1.5, this.style.flashColor, 0.9);
    flash.setBlendMode(Phaser.BlendModes.ADD);
    this.wispLayer.add(flash);
    globalScene.tweens.add({
      targets: flash,
      scale: 2,
      alpha: 0,
      duration: 420,
      ease: "Cubic.easeOut",
      onComplete: () => flash.destroy(),
    });
  }

  /** 满槽磷光 + 火种上飘（产物 startWisps） */
  private startWisps(): void {
    if (this.wispTimer) {
      return;
    }
    this.glowTween = globalScene.tweens.add({
      targets: this.glow,
      alpha: { from: 0.35, to: 0.9 },
      duration: 700,
      ease: "Sine.easeInOut",
      yoyo: true,
      repeat: -1,
    });
    this.wispTimer = globalScene.time.addEvent({
      delay: 90,
      loop: true,
      callback: () => this.spawnWisp(),
    });
  }

  private stopWisps(): void {
    this.wispTimer?.remove(false);
    this.wispTimer = null;
    this.glowTween?.stop();
    this.glowTween = null;
    this.glow.setAlpha(0);
    this.wispLayer.each((child: Phaser.GameObjects.GameObject) => globalScene.tweens.killTweensOf(child));
    this.wispLayer.removeAll(true);
  }

  private spawnWisp(): void {
    if (!this.visible || !this.parentContainer?.visible) {
      return;
    }
    const index = Phaser.Math.Between(0, this.max - 1);
    const x = this.pipX(index) + Phaser.Math.FloatBetween(-1.4, 1.4);
    const y = -GAUGE_PIP_RADIUS + Phaser.Math.FloatBetween(-0.5, 1);
    const color = Phaser.Utils.Array.GetRandom(this.style.wispColors);
    const size = Phaser.Math.FloatBetween(1.3, 2.2);
    const wisp = globalScene.add.container(x, y);
    const outer = globalScene.add.ellipse(0, 0, size * 3, size * 3.8, color, 0.35);
    outer.setBlendMode(Phaser.BlendModes.ADD);
    const middle = globalScene.add.ellipse(0, 0, size * 2, size * 2.8, color, 0.9);
    const core = globalScene.add.ellipse(0, 0.4, size, size * 1.4, this.style.flashColor, 0.95);
    core.setBlendMode(Phaser.BlendModes.ADD);
    wisp.add([outer, middle, core]);
    this.wispLayer.add(wisp);
    const rise = Phaser.Math.FloatBetween(7, 13);
    const sway = Phaser.Math.FloatBetween(1, 2.4) * (Math.random() < 0.5 ? -1 : 1);
    const duration = Phaser.Math.Between(650, 1000);
    globalScene.tweens.add({
      targets: wisp,
      y: y - rise,
      scaleX: 0.25,
      scaleY: 0.45,
      duration,
      ease: "Sine.easeIn",
      onComplete: () => wisp.destroy(),
    });
    globalScene.tweens.add({
      targets: wisp,
      alpha: 0,
      delay: duration * 0.35,
      duration: duration * 0.65,
      ease: "Quad.easeIn",
    });
    globalScene.tweens.add({
      targets: wisp,
      x: x + sway,
      duration: duration / 2,
      ease: "Sine.easeInOut",
      yoyo: true,
    });
  }

  destroy(fromScene?: boolean): void {
    this.stopWisps();
    this.clearFlames();
    this.activeTween?.remove();
    this.activeTween = null;
    super.destroy(fromScene);
  }
}
