/**
 * PKRC 战斗信息显隐工具（A3-补 第二十批 §1）
 * ---------------------------------------------------------------------------
 * 来源：产物 `loading-scene-By2k7Qfx.js`
 *   rr  → usesSquadHud                  （modeId 12/13 走「小队 HUD」）
 *   dOe → showBattleInfoExclusively     （P5X：仅显示与该宝可梦同侧的那只）
 *   MOe → showBattleInfoForActorOnly    （P5X：全场仅显示该宝可梦）
 *   另含 `Pokemon.setBattleInfoVisible` 的语义来源（method 定义在 field/pokemon.ts）
 */

import { globalScene } from "#app/global-scene";
import type { Pokemon } from "#field/pokemon";

/**
 * 产物 `rr` — 是否使用「小队 HUD」模式。
 * 判据：`gameMode.modeId === 12 || gameMode.modeId === 13`
 * （fork 扩展枚举：ERYOU=12；13 为另一扩展模式，产物未给 modeName ⇒ 按数值照实还原）。
 */
export function usesSquadHud(gameMode?: { modeId?: number } | null): boolean {
  return gameMode?.modeId === 12 || gameMode?.modeId === 13;
}

/**
 * 产物 `dOe` — 仅显示与该宝可梦同侧的一只的战斗信息（**P5X 专用**）。
 * 非 P5X 或入参为空时不动作。
 */
export function showBattleInfoExclusively(pokemon: Pokemon | null | undefined): void {
  if (!pokemon || !globalScene.gameMode?.isP5X) {
    return;
  }
  for (const fieldPokemon of globalScene.getField()) {
    if (fieldPokemon && fieldPokemon.isPlayer() === pokemon.isPlayer()) {
      fieldPokemon.setBattleInfoVisible(fieldPokemon === pokemon);
    }
  }
}

/**
 * 产物 `MOe` — 全场仅显示该宝可梦的战斗信息（**P5X 专用**）。
 * 非 P5X 或入参为空时不动作。
 */
export function showBattleInfoForActorOnly(pokemon: Pokemon | null | undefined): void {
  if (!pokemon || !globalScene.gameMode?.isP5X) {
    return;
  }
  for (const fieldPokemon of globalScene.getField()) {
    if (fieldPokemon) {
      fieldPokemon.setBattleInfoVisible(fieldPokemon === pokemon);
    }
  }
}
