import { globalScene } from "#app/global-scene";
import { allMoves } from "#data/data-lists";
import { MoveTarget } from "#enums/move-target";
import type { Pokemon } from "#field/pokemon";
import { applyMoveAttrs } from "#moves/apply-attrs";
import type { Move } from "#moves/move";
import { PokemonHealPhase } from "#phases/pokemon-heal-phase";
import { NumberHolder } from "#utils/value-holder";

/* eslint-disable @typescript-eslint/no-explicit-any */

// ─────────────────────────────────────────────────────────────
// 1. 战斗信息刷新（产物 `Pb`）
// ─────────────────────────────────────────────────────────────

/**
 * 产物 `Pb` — 刷新宝可梦的战斗信息（HP 条 / 状态图标）。
 * 语义：`pokemon?.getBattleInfo() && pokemon.updateInfo()` —— 仅在该宝可梦
 * **当前有战报对象**时才刷新（不在场 / 未进入战斗时不动作）。
 */
export function refreshBattleInfo(pokemon?: Pokemon | null): void {
  if (pokemon?.getBattleInfo()) {
    pokemon.updateInfo();
  }
}

// ─────────────────────────────────────────────────────────────
// 2. 治疗应用（产物 `lPe`）—— 魔改自建，上游无同名实现
// ─────────────────────────────────────────────────────────────

/**
 * 产物 `lPe` — 对目标施加治疗量（**保留产物的双分支语义**）。
 *
 * - `amount <= 0` → 直接返回（不与上游一样打 warn）。
 * - 目标**在场**且 `battlerIndex >= 0` → 走 `PokemonHealPhase`（带治疗动画，不可满血）。
 * - 目标**不在场**（替补席）→ 直接改 `hp`（受 `getMaxHp()` 上限约束）并刷新战斗信息。
 *
 * @param pokemon 目标宝可梦
 * @param amount  治疗量（> 0）
 */
export function applyHeal(pokemon: Pokemon, amount: number): void {
  if (amount <= 0) {
    return;
  }
  const battlerIndex = pokemon.getBattlerIndex();
  if (pokemon.isOnField() && battlerIndex >= 0) {
    // 产物：`E.unshiftPhase(new mi(i, s, null, !0, !1))`
    // → PokemonHealPhase(battlerIndex, hpHealed, message=null, showFullHpMessage=true, skipAnim=false)
    globalScene.phaseManager.unshiftPhase(new PokemonHealPhase(battlerIndex, amount, null, true, false));
    return;
  }
  pokemon.hp = Math.min(pokemon.getMaxHp(), pokemon.hp + amount);
  refreshBattleInfo(pokemon);
}

// ─────────────────────────────────────────────────────────────
// 3. 动态群体化判定（产物 `AOe` / `sS`）
// ─────────────────────────────────────────────────────────────

/**
 * 产物 `AOe` — 「视作敌方群体」的目标集合（`ALL_NEAR_ENEMIES` / `ALL_ENEMIES`）。
 *
 * 用途：`isMoveDynamicallySpread` 与 ERYOU 的 `isSpreadEnemyTarget` 共用。
 * 注：类型取 `number` 而非 `MoveTarget`，因调用侧拿到的是 `NumberHolder.value`（`number`）。
 */
export const DYNAMIC_SPREAD_ENEMY_TARGETS: Set<number> = new Set<number>([
  MoveTarget.ALL_NEAR_ENEMIES,
  MoveTarget.ALL_ENEMIES,
]);

/**
 * 产物 `sS` — 招式是否**动态群体化**。
 *
 * 语义：招式带 `VariableTargetAttr`（目标运行期可变）时，对每个对手应用该属性，
 * 若最终解析出的 `MoveTarget` 落在 `DYNAMIC_SPREAD_ENEMY_TARGETS` 内 → 视为群体招式。
 *
 * ⚠️ 产物传的是属性**类**（`zR = VariableTargetAttr`）；锚点树为字符串键，故传 `"VariableTargetAttr"`。
 */
export function isMoveDynamicallySpread(user: Pokemon, move: Move): boolean {
  const moveData = allMoves[move.id];
  if (!moveData || !moveData.hasAttr("VariableTargetAttr")) {
    return false;
  }
  const targetHolder = new NumberHolder(0);
  user.getOpponents().forEach((opponent) => {
    applyMoveAttrs("VariableTargetAttr", user, opponent, moveData, targetHolder);
  });
  return DYNAMIC_SPREAD_ENEMY_TARGETS.has(targetHolder.value);
}

// ─────────────────────────────────────────────────────────────
// 4. 治疗转换目标提供者（产物 `PIe` / `_Ie`）
// ─────────────────────────────────────────────────────────────

/** 提供者返回值：重定向后的目标（战斗位索引）+ 是否群体 */
export interface HealerConversionTarget {
  targets: number[];
  multiple: boolean;
}

/**
 * 治疗转换目标提供者签名。
 * @param user 使用者
 * @param move 使用的招式
 * @returns 重定向结果；`undefined` = 不拦截（走原逻辑）
 */
export type HealerConversionTargetProvider = (
  user: Pokemon,
  move: Move,
) => HealerConversionTarget | undefined;

/** 产物 `Iae` — 提供者模块级单例（`PIe` 写入 / `_Ie` 读取） */
let healerConversionTargetProvider: HealerConversionTargetProvider | undefined;

/**
 * 产物 `PIe` — 注册「治疗转换」目标提供者。
 * 由 healer 系统在初始化时注入（把对敌伤害招式重定向为我方目标）。
 */
export function setHealerConversionTargetProvider(provider: HealerConversionTargetProvider): void {
  healerConversionTargetProvider = provider;
}

/** 产物 `_Ie` — 读取当前提供者（未注册返回 `undefined`） */
export function getHealerConversionTargetProvider(): HealerConversionTargetProvider | undefined {
  return healerConversionTargetProvider;
}

/**
 * 产物 `Mhe` — 把「主目标」排到目标列表首位（ERYOU 群攻主目标选择的展开）。
 * 规则：目标不足 2 个时只返回主目标；否则 `[主目标, ...其余目标]`。
 */
export function orderTargetsFromPrimaryTarget(
  primaryTarget: number,
  targets: readonly number[] | undefined,
): number[] {
  if (!targets || targets.length <= 1) {
    return [primaryTarget];
  }
  return [primaryTarget, ...targets.filter(t => t !== primaryTarget)];
}
