import type { CustomPokemonData } from "#data/pokemon-data";

/* eslint-disable @typescript-eslint/no-explicit-any */

/**
 * 初始化魔改在 `CustomPokemonData` 上追加的全部计数器字段。
 * 由上游构造器末尾调用（见 `src/data/pokemon/pokemon-data.ts` 的 PKRC 注入点）。
 */
export function initModCustomPokemonData(data: CustomPokemonData): void {
  // — 天赋 · 魔火 / 虫眼 —
  data.menghuoMenghuoWave = data.menghuoMenghuoWave ?? -1;
  data.menghuoMenghuoFireStacks = data.menghuoMenghuoFireStacks ?? 0;
  data.bugYanWave = data.bugYanWave ?? -1;
  data.bugYanTriggersThisWave = data.bugYanTriggersThisWave ?? 0;
  data.bugYanPermanentStacks = data.bugYanPermanentStacks ?? 0;
  // — 天赋 · 各纪元（年代）加成 —
  data.iceAgeSpDefBoost = data.iceAgeSpDefBoost ?? 0;
  data.iceAgeAllStatsBoost = data.iceAgeAllStatsBoost ?? 0;
  data.iceAgeAtkBoost = data.iceAgeAtkBoost ?? 0;
  data.iceAgeDefReduction = data.iceAgeDefReduction ?? 0;
  data.stoneAgeDefBoost = data.stoneAgeDefBoost ?? 0;
  data.stoneAgeAllStatsBoost = data.stoneAgeAllStatsBoost ?? 0;
  data.stoneAgeAtkBoost = data.stoneAgeAtkBoost ?? 0;
  data.stoneAgeSpDefReduction = data.stoneAgeSpDefReduction ?? 0;
  data.industrialAgeDefBoost = data.industrialAgeDefBoost ?? 0;
  data.industrialAgeSpDefBoost = data.industrialAgeSpDefBoost ?? 0;
  data.industrialAgeAllStatsBoost = data.industrialAgeAllStatsBoost ?? 0;
  data.industrialAgeSpdBoost = data.industrialAgeSpdBoost ?? 0;
  data.industrialAgeSpAtkReduction = data.industrialAgeSpAtkReduction ?? 0;
  data.infoAgeSpdBoost = data.infoAgeSpdBoost ?? 0;
  data.infoAgeAllStatsBoost = data.infoAgeAllStatsBoost ?? 0;
  data.infoAgePoisonSpdBoost = data.infoAgePoisonSpdBoost ?? 0;
  data.infoAgePoisonSpAtkBoost = data.infoAgePoisonSpAtkBoost ?? 0;
  data.infoAgePoisonSpAtkReduction = data.infoAgePoisonSpAtkReduction ?? 0;
  data.infoAgePoisonSpDefReduction = data.infoAgePoisonSpDefReduction ?? 0;
  data.totemAgeHpBoost = data.totemAgeHpBoost ?? 0;
  data.totemAgeAllStatsBoost = data.totemAgeAllStatsBoost ?? 0;
  data.totemAgeAtkBoost = data.totemAgeAtkBoost ?? 0;
  data.totemAgeSpdBoost = data.totemAgeSpdBoost ?? 0;
  data.totemAgeSpDefReduction = data.totemAgeSpDefReduction ?? 0;
  // — 等价交换 / 同性相吸 / 一箭倾心 —
  data.dengjiajiaohuan_wave = data.dengjiajiaohuan_wave ?? -1;
  data.dengjiajiaohuan_triggered = data.dengjiajiaohuan_triggered ?? false;
  data.tongxingSyncedStatus = data.tongxingSyncedStatus ?? undefined;
  data.yijianQingyuanWave = data.yijianQingyuanWave ?? -1;
  data.yijianQingyuanStatStacks = data.yijianQingyuanStatStacks ?? 0;
  data.yijianQingyuanBoostWave = data.yijianQingyuanBoostWave ?? -1;
  data.yijianQingyuanBoostsThisWave = data.yijianQingyuanBoostsThisWave ?? 0;
  // — 星象 / 偷心怪盗 / 解明 —
  data.xingxiangIndex = data.xingxiangIndex ?? 0;
  data.xingxiangCycles = data.xingxiangCycles ?? 0;
  data.xingxiangWave = data.xingxiangWave ?? -1;
  data.xingxiangEarthWave = data.xingxiangEarthWave ?? -1;
  data.xingxiangEarthTurn = data.xingxiangEarthTurn ?? -1;
  data.callingCards = data.callingCards ?? 0;
  data.callingCardEndureWave = data.callingCardEndureWave ?? -1;
  data.callingCardGuardTurn = data.callingCardGuardTurn ?? -1;
  data.callingCardGainTurn = data.callingCardGainTurn ?? -1;
  data.callingCardGainTargets = data.callingCardGainTargets ?? {};
  data.jiemingCooldowns = data.jiemingCooldowns ?? {};
  // — 赤心（CHIXIN）—
  data.chiXinStacks = data.chiXinStacks ?? 0;
  data.chiXinReadyRound = data.chiXinReadyRound ?? -1;
  data.chiXinReadyWave = data.chiXinReadyWave ?? -1;
  data.chiXinGainAction = data.chiXinGainAction ?? -1;
  data.chiXinGainCount = data.chiXinGainCount ?? 0;
  data.chiXinBurnRound = data.chiXinBurnRound ?? -1;
  data.chiXinEndureWave = data.chiXinEndureWave ?? -1;
  data.chiXinGuardTurn = data.chiXinGuardTurn ?? -1;
  data.chiXinPursuitRound = data.chiXinPursuitRound ?? -1;
  data.chiXinPendingSpread = data.chiXinPendingSpread ?? false;
  data.chiXinStageGain = data.chiXinStageGain ?? 0;
  // — 海之守护（MANAPHY）—
  data.seaGuardLowHpWave = data.seaGuardLowHpWave ?? -1;
  data.seaGuardOpenedWave = data.seaGuardOpenedWave ?? -1;
  data.seaGuardChaseAction = data.seaGuardChaseAction ?? -1;
  // — 念力（NIANLI）—
  data.nianLiStacks = data.nianLiStacks ?? 0;
  data.nianLiGainTurn = data.nianLiGainTurn ?? -1;
  data.nianLiEndureWave = data.nianLiEndureWave ?? -1;
  data.nianLiBurstTurn = data.nianLiBurstTurn ?? -1;
  data.nianLiAutoAttack = data.nianLiAutoAttack ?? false;
  data.nianLiBuffActive = data.nianLiBuffActive ?? false;
  // — 旋律（MELOETTA）—
  data.meloettaBeats = data.meloettaBeats ?? 0;
  data.meloettaWave = data.meloettaWave ?? -1;
  data.meloettaDanceBonus = data.meloettaDanceBonus ?? 0;
  data.meloettaDanceTurns = data.meloettaDanceTurns ?? 0;
  // — 编织（MEW）—
  data.mewWeave = data.mewWeave ?? 0;
  data.mewWeaveGained = data.mewWeaveGained ?? 0;
  data.mewWeaveTurn = data.mewWeaveTurn ?? -1;
  data.mewImplantTypes = data.mewImplantTypes ?? [];
  data.mewImplantFromAll = data.mewImplantFromAll ?? false;
  // — 治疗（HEALER）—
  data.healerVigor = data.healerVigor ?? 0;
  data.healerVigorAction = data.healerVigorAction ?? -1;
  data.healerChantAction = data.healerChantAction ?? -1;
  data.healerWishWave = data.healerWishWave ?? -1;
  data.healerShieldEntries = data.healerShieldEntries ?? [];
  data.healerVigorRoundKey = data.healerVigorRoundKey ?? -1;
  data.healerVigorRoundGain = data.healerVigorRoundGain ?? 0;
}
