/**
 * 产物 `Fge(n)` = `pickGuardianSpecialMove(pokemon)`（@4427261 len=1698）
 *
 * 守门员 AI 的**特殊出招**决策，返回 `null` 表示「交回通用 AI」。
 * 两个专属 AI：
 *
 * ### 杰拉奇（`jirachi`）
 * 按**当前星象**决定出招类别 —— 这是全场最反直觉的一段，务必照抄：
 * - 火象（`XINGXIANG_FIRE`）⇒ 只出**非变化**招式
 * - 风象（`XINGXIANG_WIND`）⇒ 只出**变化**招式
 * - 土/水象 ⇒ `null`（走通用 AI）
 *
 * ### 沙奈朵（`gardevoir`）
 * 1. 对手睡眠 ⇒ 优先 `DREAM_EATER`
 * 2. 首次 `REST` 由「掉血」触发（`guardianPrevHp` 比对），之后每 3 回合一次
 * 3. 兜底：优先非变化且非 `DREAM_EATER`，再兜非 `DREAM_EATER`
 *
 * ⚠️ `guardianFirstRestUsed` / `guardianPrevHp` 写在 `pokemon.customPokemonData` 上，
 *    **跨回合持久** —— 别改成局部变量，否则「首次休息」判定每回合都会重触发。
 * ⚠️ 随机数用 `globalScene.randBattleSeedInt`（战斗种子）。
 *    `randSeedInt` 在非战斗上下文取值不同，会破坏回放一致性。
 */
export function pickGuardianSpecialMove(
  pokemon: any,
): { move: number; targets: number[] } | null {
  if (!globalScene.currentBattle?.guardianBoss) {
    return null;
  }

  // ── 杰拉奇：按星象分流 ──
  if (pokemon.species.speciesId === SpeciesId.JIRACHI) {
    const xingxiang = getXingxiangIndex(pokemon);
    const usable = pokemon
      .getMoveset()
      .filter((m: any) => !!m && m.isUsable(pokemon, false, true));
    if (xingxiang === XINGXIANG_FIRE) {
      const attackMoves = usable.filter((m: any) => m.getMove().category !== MoveCategory.STATUS);
      if (attackMoves.length > 0) {
        const picked = attackMoves[globalScene.randBattleSeedInt(attackMoves.length)];
        return { move: picked.moveId, targets: pokemon.getNextTargets(picked.moveId) };
      }
    }
    if (xingxiang === XINGXIANG_WIND) {
      const statusMoves = usable.filter((m: any) => m.getMove().category === MoveCategory.STATUS);
      if (statusMoves.length > 0) {
        const picked = statusMoves[globalScene.randBattleSeedInt(statusMoves.length)];
        return { move: picked.moveId, targets: pokemon.getNextTargets(picked.moveId) };
      }
    }
    return null;
  }

  // ── 沙奈朵：食梦 → 休息节奏 → 普通攻击 ──
  if (pokemon.species.speciesId === SpeciesId.GARDEVOIR) {
    const usable = pokemon
      .getMoveset()
      .filter((m: any) => !!m && m.isUsable(pokemon, false, true));
    const opponent = pokemon
      .getOpponents()
      .find((o: any) => o?.isActive(true) && !o.isFainted());

    // ① 对手睡眠 ⇒ 食梦
    if (opponent?.status?.effect === StatusEffect.SLEEP) {
      const dreamEater = usable.find((m: any) => m.moveId === MoveId.DREAM_EATER);
      if (dreamEater) {
        return { move: dreamEater.moveId, targets: pokemon.getNextTargets(dreamEater.moveId) };
      }
    }

    // ② 休息节奏
    const data = pokemon.customPokemonData;
    const turn = globalScene.currentBattle?.turn ?? 0;
    if (data?.guardianFirstRestUsed) {
      // 已用过首次休息 ⇒ 之后每 3 回合一次
      if (turn > 0 && turn % 3 === 0) {
        const rest = usable.find((m: any) => m.moveId === MoveId.REST);
        if (rest) {
          return { move: rest.moveId, targets: pokemon.getNextTargets(rest.moveId) };
        }
      }
    } else {
      // 首次休息：掉血即触发（记录上一回合 HP 做比对）
      const prevHp = data?.guardianPrevHp ?? pokemon.getMaxHp();
      const hasLostHp = pokemon.hp < prevHp;
      data.guardianPrevHp = pokemon.hp;
      if (hasLostHp) {
        const rest = usable.find((m: any) => m.moveId === MoveId.REST);
        if (rest) {
          data.guardianFirstRestUsed = true;
          return { move: rest.moveId, targets: pokemon.getNextTargets(rest.moveId) };
        }
      }
    }

    // ③ 兜底：先非变化且非食梦，再兜非食梦
    const attackMoves = usable.filter(
      (m: any) => m.getMove().category !== MoveCategory.STATUS && m.moveId !== MoveId.DREAM_EATER,
    );
    if (attackMoves.length > 0) {
      const picked = attackMoves[globalScene.randBattleSeedInt(attackMoves.length)];
      return { move: picked.moveId, targets: pokemon.getNextTargets(picked.moveId) };
    }
    const anyNonDreamEater = usable.filter((m: any) => m.moveId !== MoveId.DREAM_EATER);
    if (anyNonDreamEater.length > 0) {
      const picked = anyNonDreamEater[globalScene.randBattleSeedInt(anyNonDreamEater.length)];
      return { move: picked.moveId, targets: pokemon.getNextTargets(picked.moveId) };
    }
    return null;
  }

  return null;
}

