/** 产物 `fre` — 战斗中的天赋运行时文本行（A3-补 第四批：**已补全**，替换原空壳） */
export function getBattleTalentRuntimeLines(pokemon: any): string[] {
  const lines: string[] = [];

  // BUG燕（产物 `xR(n, e.SWELLOW, Xw)` · `Xw` = `"bug_yan"`）
  if (isPlayerSpeciesTalentActive(pokemon, SpeciesId.SWELLOW, "bug_yan")) {
    // ⚠️ A3-补 挂账：`syncBugYanWaveState`（产物 `Dre`）未迁移 ⇒ 可选调用
    (globalThis as any).__syncBugYanWaveState?.(pokemon);
    const stacks = pokemon.customPokemonData.bugYanPermanentStacks ?? 0;
    const used = pokemon.customPokemonData.bugYanTriggersThisWave ?? 0;
    const remain = Math.max(0, 3 - used);
    lines.push(`BUG燕 加攻${stacks}层 剩余触发次数: ${remain}`);
  }

  // 猛火（产物 `xR(n, e.INFERNAPE, Zw)` · `Zw` = `"menghuo_menghuo"`）
  if (isPlayerSpeciesTalentActive(pokemon, SpeciesId.INFERNAPE, "menghuo_menghuo")) {
    // ⚠️ A3-补 挂账：`syncMenghuoMenghuoWaveState`（产物 `Qw`）未迁移 ⇒ 可选调用
    (globalThis as any).__syncMenghuoMenghuoWaveState?.(pokemon);
    const stacks = pokemon.customPokemonData.menghuoMenghuoFireStacks ?? 0;
    lines.push(`猛火 ${stacks}层`);
  }

  // 一剑清源（产物 `Rg`）
  if (isYijianQingyuanActiveFor(pokemon)) {
    const data = pokemon.customPokemonData;
    const stacks = data?.yijianQingyuanStatStacks ?? 0;
    const thisWave = data && data.yijianQingyuanBoostWave === getCurrentWave() ? (data.yijianQingyuanBoostsThisWave ?? 0) : 0;
    lines.push(`一见情缘 ${stacks}层(+${(stacks * 5.2).toFixed(1)}%) 本波${thisWave}/3`);
  }

  // 星象（产物 `PS` / `kw(CI(n))`）
  if (isXingxiangActiveFor(pokemon)) {
    const name = getXingxiangName(getXingxiangIndex(pokemon));
    const cycles = pokemon.customPokemonData?.xingxiangCycles ?? 0;
    lines.push(`星象 [${name}] 轮回${cycles}层(+${cycles * 6}%)`);
  }

  // ── 时代天赋（仅玩家侧，产物 5 组分支）──
  if (pokemon.isPlayer()) {
    const mgr = getTalentManager();
    const has = (id: string) => (mgr && mgr.hasTalent(id)) || hasTalentReleaseTalentInParty(pokemon, id);

    // 冰河期
    if (has("bingheqi")) {
      const b = getIceAgeStatBoosts(pokemon);
      const s = getIceAgeStats();
      if (b.spDefBoost > 0 || b.allStatsBoost > 0 || b.atkBoost > 0 || b.defReduction > 0) {
        const attr: string[] = [];
        if (b.allStatsBoost > 0) attr.push(`冰属性+${b.allStatsBoost}%`);
        if (b.atkBoost > 0 || b.defReduction > 0) attr.push(`水属性+${b.atkBoost}%-${b.defReduction}%`);
        if (attr.length > 0) lines.push(`冰河期 ${attr.join(" ")}`);
        const regi: string[] = [];
        if (b.spDefBoost > 0) regi.push(`雷吉艾斯+${b.spDefBoost}%`);
        regi.push(`本波次剩余(${s.waveTriggersCount}/${s.maxWaveTriggers})`);
        lines.push(`冰河期 ${regi.join(" ")}`);
      }
    }

    // 石器时代
    if (has("shiqishidai")) {
      const b = getStoneAgeStatBoosts(pokemon);
      const s = getStoneAgeStats();
      if (b.defBoost > 0 || b.allStatsBoost > 0 || b.atkBoost > 0 || b.spDefReduction > 0) {
        const attr: string[] = [];
        if (b.allStatsBoost > 0) attr.push(`岩石属性+${b.allStatsBoost}%`);
        if (b.atkBoost > 0 || b.spDefReduction > 0) attr.push(`地面属性+${b.atkBoost}%-${b.spDefReduction}%`);
        if (attr.length > 0) lines.push(`石器时代 ${attr.join(" ")}`);
        const regi: string[] = [];
        if (b.defBoost > 0) regi.push(`雷吉洛克+${b.defBoost}%`);
        regi.push(`本波次剩余(${s.waveTriggersCount}/${s.maxWaveTriggers})`);
        lines.push(`石器时代 ${regi.join(" ")}`);
      }
    }

    // 工业革命
    if (has("gongyegeming")) {
      const b = getIndustrialAgeStatBoosts(pokemon);
      const s = getIndustrialAgeStats();
      if (b.defBoost > 0 || b.spDefBoost > 0 || b.allStatsBoost > 0 || b.spdBoost > 0 || b.spAtkReduction > 0) {
        const attr: string[] = [];
        if (b.allStatsBoost > 0) attr.push(`钢属性+${b.allStatsBoost}%`);
        if (b.spdBoost > 0 || b.spAtkReduction > 0) attr.push(`火属性+${b.spdBoost}%-${b.spAtkReduction}%`);
        if (attr.length > 0) lines.push(`工业革命 ${attr.join(" ")}`);
        const regi: string[] = [];
        if (b.defBoost > 0 || b.spDefBoost > 0) regi.push(`雷吉斯奇鲁+${b.defBoost}%+${b.spDefBoost}%`);
        regi.push(`本波次剩余(${s.waveTriggersCount}/${s.maxWaveTriggers})`);
        lines.push(`工业革命 ${regi.join(" ")}`);
      }
    }

    // 信息文明
    if (has("xinxiwenming")) {
      const b = getInfoAgeStatBoosts(pokemon);
      const s = getInfoAgeStats();
      if (b.spdBoost > 0 || b.allStatsBoost > 0 || b.poisonSpdBoost > 0 || b.poisonSpDefReduction > 0) {
        const attr: string[] = [];
        if (b.allStatsBoost > 0) attr.push(`电属性+${b.allStatsBoost}%`);
        if (b.poisonSpdBoost > 0 || b.poisonSpDefReduction > 0) attr.push(`毒属性+${b.poisonSpdBoost}%-${b.poisonSpDefReduction}%`);
        if (attr.length > 0) lines.push(`信息文明 ${attr.join(" ")}`);
        const regi: string[] = [];
        if (b.spdBoost > 0) regi.push(`雷吉艾勒奇+${b.spdBoost}%`);
        regi.push(`本波次剩余(${s.waveTriggersCount}/${s.maxWaveTriggers})`);
        lines.push(`信息文明 ${regi.join(" ")}`);
      }
    }

    // 图腾崇拜
    if (has("tutengchongbai")) {
      const b = getTotemAgeStatBoosts(pokemon);
      const s = getTotemAgeStats();
      if (b.hpBoost > 0 || b.allStatsBoost > 0 || b.atkBoost > 0 || b.spdBoost > 0 || b.spDefReduction > 0) {
        const attr: string[] = [];
        if (b.allStatsBoost > 0) attr.push(`龙属性+${b.allStatsBoost}%`);
        if (b.atkBoost > 0 || b.spdBoost > 0 || b.spDefReduction > 0) {
          attr.push(`一般属性+${b.atkBoost}%/+${b.spdBoost}%-${b.spDefReduction}%`);
        }
        if (attr.length > 0) lines.push(`图腾崇拜 ${attr.join(" ")}`);
        const regi: string[] = [];
        if (b.hpBoost > 0) regi.push(`雷吉铎拉戈+${b.hpBoost}%`);
        regi.push(`本波次剩余(${s.waveTriggersCount}/${s.maxWaveTriggers})`);
        lines.push(`图腾崇拜 ${regi.join(" ")}`);
      }
    }
  }

  return lines;
}

/** 产物 `Oue` — 读档后刷新天赋 HUD */
export function refreshTalentRuntimeHudAfterLoad(): void {
  if (!globalScene) return;
  try {
    const party = globalScene.getPlayerParty();
    for (const pokemon of party) {
      if (!pokemon || pokemon.isFainted()) continue;
      const lines = getBattleTalentRuntimeLines(pokemon);
      if (lines.length > 0) {
        globalScene.setTalentRuntimeHudText(lines.join("\n"));
        return;
      }
    }
    globalScene.setTalentRuntimeHudText("");
  } catch (err) {
    console.error("[天赋HUD] 读档后刷新失败:", err);
  }
}

/** 产物 `pge` — 构建守护者天赋行（敌方天赋列表展示） */
export function buildGuardianTalentLines(pokemon: any): string[] {
  const enemyManager = getEnemyTalentManager();
  const registry = getTalentRegistry();
  const lines: string[] = [];
  for (const [id, stacks] of enemyManager.getTalents()) {
    if (id === "xingxiang") {
      lines.push(`星象 [${getXingxiangName(getXingxiangIndex(pokemon))}]`);
      continue;
    }
    const talent = registry.getTalent(id);
    if (!talent) continue;
    const name = i18next.t(talent.name, talent.name);
    lines.push(stacks > 1 && id !== "shengmingjiqu" ? `${name} ×${stacks}` : name);
  }
  return lines;
}

/** 产物 `Ene` — 构建守护者天赋 id 列表（含额外池随机补充） */
export function buildGuardianTalentIds(pokemon: any, species: number): string[] {
  const ids = pokemon.talentForSpecies(species);
  if (pokemon.extraTalentPool && pokemon.extraTalentCount) {
    const [min, max] = pokemon.extraTalentCount;
    const count = min + randInt(max - min + 1);
    const pool = [...pokemon.extraTalentPool];
    for (let i = pool.length - 1; i > 0; i--) {
      const j = randInt(i + 1);
      [pool[i], pool[j]] = [pool[j], pool[i]];
    }
    ids.push(...pool.slice(0, count));
  }
  return ids;
}

