/** 产物 `O2` — 天赋图鉴管理器 */
export class TalentCodexManager {
  private discoveredTalents = new Set<string>();

  markDiscovered(id: string): void {
    this.discoveredTalents.add(id);
  }

  isDiscovered(id: string): boolean {
    return this.discoveredTalents.has(id);
  }

  getProgress(total?: number): { discovered: number; total: number } {
    return { discovered: this.discoveredTalents.size, total: total ?? this.discoveredTalents.size };
  }

  serialize(): string {
    return JSON.stringify({ discoveredTalents: Array.from(this.discoveredTalents) });
  }

  deserialize(data: string): void {
    try {
      const parsed = JSON.parse(data);
      if (parsed.discoveredTalents && Array.isArray(parsed.discoveredTalents)) {
        this.discoveredTalents = new Set(parsed.discoveredTalents);
      } else {
        console.warn("Invalid codex data format, resetting to empty");
        this.discoveredTalents = new Set();
      }
    } catch (err) {
      console.error("Failed to deserialize codex data:", err);
      this.discoveredTalents = new Set();
    }
  }

  reset(): void {
    this.discoveredTalents.clear();
  }

  getDiscoveredTalents(): string[] {
    return Array.from(this.discoveredTalents);
  }
}

let talentCodexManager: TalentCodexManager | null = null;

/** 产物 `mue` — 取天赋图鉴管理器 */
export function getTalentCodexManager(): TalentCodexManager {
  return (talentCodexManager ??= new TalentCodexManager());
}

// ─────────────────────────────────────────────────────────────
// 11b. Instant Effect 机制（产物 `OK` / `rN` / `v_e`，A3-补 第三十批 §7-b）
// ---------------------------------------------------------------------------
// 来源：loading-scene-By2k7Qfx.js @3925551~3926800（紧跟 TalentManagerV2 之前）。
//   `OK` = instant effect 注册表（Map<talentId, handler>）
//   `rN` = registerInstantEffect（重复注册覆盖并告警）
//   `v_e` = runInstantEffect（按 talent.id 查表执行，命中返回 true）
// 入口：TalentManagerV2.acquireTalent 末尾 `runInstantEffect(talent, stacks)`。
// ---------------------------------------------------------------------------

/** instant effect 处理器签名（产物 `OK` 的值类型） */
type InstantEffectHandler = (talent: Talent, stacks: number) => void;

/** 产物 `OK` — instant effect 注册表（key = talent id） */
const instantEffectHandlers = new Map<string, InstantEffectHandler>();

/** 产物 `rN` — 注册天赋 instant effect（重复注册覆盖并告警） */
export function registerInstantEffect(talentId: string, handler: InstantEffectHandler): void {
  if (instantEffectHandlers.has(talentId)) {
    debugLog("talent", `[InstantEffect] 天赋 "${talentId}" 已注册过处理器，将被覆盖`);
  }
  instantEffectHandlers.set(talentId, handler);
}

/** 产物 `v_e` — 执行天赋 instant effect（按 talent.id 查表，命中返回 true） */
export function runInstantEffect(talent: Talent, stacks: number): boolean {
  const handler = instantEffectHandlers.get(talent.id);
  if (handler) {
    handler(talent, stacks);
    return true;
  }
  return false;
}

