/**
 * 星象名称表（产物 `Use` = ["火象","水象","土象","风象"]，index 0~3）
 */
export const XINGXIANG_NAMES: string[] = ["火象", "水象", "土象", "风象"];

/**
 * 星象轮回常量（产物 `og=0, cre=1, kNe=2, hre=3`，@5371117）
 * ⚠️ E13：A3 原 `XINGXIANG_OTHER = 1` 错位（1 是 `cre`/水象；`hre` = 3/风象）。
 *    风象分支（`handleXingxiangTalentEffect` 的 else-if）因此恒不触发，已改为 `XINGXIANG_WIND`。
 */
export const XINGXIANG_FIRE = 0; // 产物 `og`（火象）
export const XINGXIANG_WATER = 1; // 产物 `cre`（水象）
export const XINGXIANG_EARTH = 2; // 产物 `kNe`（土象）
export const XINGXIANG_WIND = 3; // 产物 `hre`（风象）

/** 产物 `Mre` — 重算属性并按比例保留当前 HP（通用工具，星象满轮/等价交换共用） */
export function recalcStatsPreservingHp(pokemon: any): void {
  const maxHp = pokemon.getMaxHp();
  const ratio = maxHp > 0 ? pokemon.hp / maxHp : 1;
  pokemon.calculateStats();
  const newMaxHp = pokemon.getMaxHp();
  pokemon.hp = Math.min(Math.floor(newMaxHp * ratio), newMaxHp);
  pokemon.updateInfo();
}

/** 产物 `PS` — 星象天赋激活判定（基拉祈持有「星象」天赋） */
export function isXingxiangActiveFor(pokemon: any): boolean {
  // 产物 `VNe="xingxiang"`（天赋 id 字面量，无独立 keepNames 名）
  return isPlayerSpeciesTalentActive$1(pokemon, [SpeciesId.JIRACHI], "xingxiang");
}

/** 产物 `CI` — 当前星象 index（越界回退 0） */
export function getXingxiangIndex(pokemon: any): number {
  const index = pokemon.customPokemonData?.xingxiangIndex ?? 0;
  return index >= 0 && index <= 3 ? index : 0;
}

/** 产物 `kw` — 星象名称（入参为 **index**，非 pokemon；E13） */
export function getXingxiangName(index: number): string {
  return XINGXIANG_NAMES[index] ?? XINGXIANG_NAMES[0];
}

/**
 * 产物 `Wh` — 切换星象；切回火象时记一轮轮回并全属性 +6%（保留 HP 比例重算）。
 * @param silent 产物第 2 参 `s`：true 时不发 queueMessage（波次推进用）；`updateInfo` 恒执行（产物逗号表达式）
 */
export function switchXingxiang(pokemon: any, silent = false): void {
  if (!pokemon.customPokemonData) {
    return;
  }
  pokemon.customPokemonData.xingxiangIndex = (getXingxiangIndex(pokemon) + 1) % 4;
  const name = getXingxiangName(pokemon.customPokemonData.xingxiangIndex);
  if (pokemon.customPokemonData.xingxiangIndex === XINGXIANG_FIRE) {
    pokemon.customPokemonData.xingxiangCycles = (pokemon.customPokemonData.xingxiangCycles ?? 0) + 1;
    recalcStatsPreservingHp(pokemon);
    debugLog("talent", `[星象] ${pokemon.name} 完成第${pokemon.customPokemonData.xingxiangCycles}轮轮回，全属性+6%`);
    if (!silent) {
      globalScene.phaseManager.queueMessage(`星象完成一轮轮回！${pokemon.name}的全属性提升了6%！`);
    }
  }
  debugLog("talent", `[星象] ${pokemon.name} 星象切换为【${name}】`);
  if (!silent) {
    globalScene.phaseManager.queueMessage(`${pokemon.name}的星象切换为【${name}】！`);
  }
  pokemon.updateInfo();
}

/** 产物 `nue` — 风象效果：全队回复 50% 血量并清除异常，自身速度 +1 */
export function applyXingxiangWindEffect(pokemon: any): void {
  if (!globalScene) {
    return;
  }
  const party = pokemon.isPlayer() ? globalScene.getPlayerParty() : globalScene.getEnemyParty();
  for (const member of party) {
    if (!member || member.isFainted()) {
      continue;
    }
    const healAmount = Math.max(1, Math.floor(member.getMaxHp() * 0.5));
    const healed = member.heal(healAmount);
    if (healed > 0 && member.isOnField()) {
      globalScene.damageNumberHandler?.add(member, healed, HitResult.HEAL);
    }
    if (member.status) {
      member.resetStatus(false);
    }
    member.updateInfo();
  }
  globalScene.phaseManager.queueMessage("星象·风象发动！全队回复了50%血量，异常状态被清除了！");
  pokemon.setStatStage(Stat.SPD, Math.min(6, pokemon.getStatStage(Stat.SPD) + 1));
  pokemon.updateInfo();
  globalScene.phaseManager.queueMessage(`${pokemon.name}的速度提升了！`);
  debugLog("talent", `[星象] 风象触发：${pokemon.name} 全队回复50%并清除异常，速度+1`);
}

/** 产物 `qNe` — 星象轮回全属性倍率（1 + 轮回轮数 × 6%） */
export function getXingxiangCycleStatMultiplier(pokemon: any): number {
  if (!isXingxiangActiveFor(pokemon) || !pokemon.customPokemonData) {
    return 1;
  }
  return 1 + (pokemon.customPokemonData.xingxiangCycles ?? 0) * 0.06;
}

/** 产物 `eue` — 星象火象威力倍率（火象且非变化招式 ×14，即 +1300%） */
export function getXingxiangFirePowerMult(pokemon: any, moveCategory: MoveCategory): number {
  if (moveCategory === MoveCategory.STATUS || !isXingxiangActiveFor(pokemon)) {
    return 1;
  }
  return getXingxiangIndex(pokemon) === XINGXIANG_FIRE ? 14 : 1;
}

/** 产物 `aue` — 波次切换时推进玩家全队星象（每波次只推进一次） */
export function advanceXingxiangOnWaveChange(currentWave: number): void {
  if (!globalScene) {
    return;
  }
  const party = globalScene.getPlayerParty();
  for (const pokemon of party) {
    if (!pokemon || pokemon.isFainted() || !pokemon.customPokemonData) {
      continue;
    }
    if (!isXingxiangActiveFor(pokemon)) {
      continue;
    }
    if (pokemon.customPokemonData.xingxiangWave === currentWave) {
      continue;
    }
    pokemon.customPokemonData.xingxiangWave = currentWave;
    debugLog("talent", `[星象] 进入波次${currentWave}，${pokemon.name} 切换星象`);
    switchXingxiang(pokemon, true);
  }
}

/** 产物 `Cue` — 梦话（睡眠时按最大 HP 1/8 扣血） */
export function applyBadDreamsTalentDamage(pokemon: any): void {
  const stacks = pokemon.isPlayer()
    ? getEnemyTalentManager().getStacks(TALENT_ID_BAD_DREAMS)
    : getPlayerTalentStacks(TALENT_ID_BAD_DREAMS);
  if (pokemon.status?.effect !== StatusEffect.SLEEP || pokemon.isFainted() || stacks <= 0) return;
  const damage = Math.max(1, Math.floor(pokemon.getMaxHp() / 8));
  pokemon.damageAndUpdate(damage, HitResult.INDIRECT, false, false, true);
}


