/**
 * 产物 `Z_e` — 冰河期 AOE：自身**特防** × 3。
 * @param pokemon 时代天赋持有者（雷吉艾斯）
 */
export function applyIceAgeAoeDamage(pokemon: any): void {
  if (!globalScene) return;
  const foes = pokemon.isPlayer() ? globalScene.getEnemyField() : globalScene.getPlayerField();
  const spDef = pokemon.getStat(Stat.SPDEF, false);
  const damage = Math.floor(spDef * 3);
  debugLog("talent", `[IceAge] 触发冰河期AOE伤害: 雷吉艾斯特防=${spDef}, 伤害=${damage}`);
  for (const foe of foes) {
    if (foe && !foe.isFainted()) {
      const dealt = foe.damageAndUpdate(damage);
      globalScene.damageNumberHandler?.add(foe, dealt);
      foe.updateInfo();
      debugLog("talent", `[IceAge] 对${foe.name}造成${dealt}点伤害`);
    }
  }
}

