/** 产物 `X_e` — 冰河期永久属性提升（雷吉艾斯特防+2%；冰属性全属性+1%；水属性攻+2%/防-2%） */
export function applyIceAgePermanentStatBoosts(holder: any): void {
  if (!globalScene) return;
  const party = holder?.isPlayer() ? globalScene.getPlayerParty() : globalScene.getEnemyParty();
  for (const p of party) {
    if (!p || p.isFainted() || !p.customPokemonData) continue;
    if (holder && p.id === holder.id) {
      p.customPokemonData.iceAgeSpDefBoost += 2;
      debugLog("talent", `[IceAge] 雷吉艾斯特防永久提升+2% (总计: ${p.customPokemonData.iceAgeSpDefBoost}%)`);
    }
    if (p.isOfType(PokemonType.ICE)) {
      p.customPokemonData.iceAgeAllStatsBoost += 1;
      debugLog("talent", `[IceAge] ${p.name}(冰属性)全属性永久提升+1% (总计: ${p.customPokemonData.iceAgeAllStatsBoost}%)`);
    }
    if (p.isOfType(PokemonType.WATER)) {
      p.customPokemonData.iceAgeAtkBoost += 2;
      p.customPokemonData.iceAgeDefReduction += 2;
      debugLog("talent", `[IceAge] ${p.name}(水属性)攻击+2%/防御-2% (总计: 攻+${p.customPokemonData.iceAgeAtkBoost}%/防-${p.customPokemonData.iceAgeDefReduction}%)`);
    }
  }
}

