/** 时代天赋触发后的「全队重算属性并按比例保留 HP」（产物 5 处相同内联块） */
function recalcPartyAfterAgeBoost(holder: any): void {
  if (!globalScene) return;
  const party = holder.isPlayer() ? globalScene.getPlayerParty() : globalScene.getEnemyParty();
  for (const p of party) {
    if (p && !p.isFainted()) {
      const ratio = p.getMaxHp() > 0 ? p.hp / p.getMaxHp() : 1;
      p.calculateStats();
      const newMax = p.getMaxHp();
      p.hp = Math.min(Math.floor(newMax * ratio), newMax);
      p.updateInfo();
    }
  }
}

/** 产物（5 处内联块统一抽取）— 触发时代天赋的 AOE + 永久提升 + 属性重算 */
function triggerAgeTalentAmplify(
  ageLabel: string,
  regiLabel: string,
  enemies: any[],
  holder: any,
  applyAoe: (p: any) => void,
  applyBoosts: (p: any) => void,
): void {
  if (enemies.length <= 0) return;
  debugLog("talent", `[${ageLabel}] 检测到${enemies.length}个对方已降6级`);
  if (!holder) {
    debugLog("talent", `[${ageLabel}] 队伍中没有${regiLabel}，跳过AOE伤害`);
    return;
  }
  debugLog("talent", `[${ageLabel}] 队伍中有${regiLabel}，触发AOE伤害和永久属性提升`);
  applyAoe(holder);
  applyBoosts(holder);
  recalcPartyAfterAgeBoost(holder);
}


